```javascript
    useEffect(() => {
        PaymentMethods.clearDebitCardFormErrorAndSubmit();
        if (!Permissions.canUseWallet(props.betas)) {
            Navigation.goBack(ROUTES.SETTINGS_PAYMENTS, true)
        }
